import{_ as t,o as a,c as i,a7 as s}from"./chunks/framework.DUCm5Bu5.js";const u=JSON.parse('{"title":"Contributing","description":"Set up the toolchain, build and test, follow the project rules, and submit a reviewable change.","frontmatter":{"title":"Contributing","description":"Set up the toolchain, build and test, follow the project rules, and submit a reviewable change.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"en/project/contributing.md","filePath":"en/project/contributing.md"}'),o={name:"en/project/contributing.md"};function n(d,e,r,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h2 id="what-this-page-covers" tabindex="-1">What this page covers <a class="header-anchor" href="#what-this-page-covers" aria-label="Permalink to &quot;What this page covers&quot;">​</a></h2><p>This page takes a new contributor from a clean machine to a change that can be reviewed and merged: the rules to read first, the toolchain, the build and validation commands, the repository map, the obligations a change carries, and the review process. Bubble Fighter Fantasy is a prerelease community server maintained by Fantasy Tale Studio; it is written in C# on .NET 10 and composed from plugins.</p><p><strong>Who this is for.</strong> First-time contributors, and anyone who needs to reproduce or review another contributor&#39;s change.</p><p><strong>Before you start.</strong></p><ul><li>Read <code>AGENTS.md</code> and <code>CONTRIBUTING.md</code> at the repository root. <code>AGENTS.md</code> is binding: it holds the architecture, packet-data, evidence, naming and language rules.</li><li>Install the .NET 10 SDK and Git; you need both to build and run the server.</li><li>A real game client and its data are needed only for native-client testing. The repository ships neither.</li></ul><h2 id="read-the-rules-first" tabindex="-1">Read the rules first <a class="header-anchor" href="#read-the-rules-first" aria-label="Permalink to &quot;Read the rules first&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>What it means in practice</th></tr></thead><tbody><tr><td>Everything is a plugin</td><td>New capability ships as a plugin row in a profile, not as a special case in the kernel or host.</td></tr><tr><td>Context is the service registry</td><td>Consume services by declared interface type; never reach into another plugin&#39;s classes.</td></tr><tr><td>Registrations are effects</td><td>Every <code>Register*</code>/<code>On*</code> returns a disposer; hand it to <code>context.Effect(...)</code> so unload unwinds in reverse order.</td></tr><tr><td>No hard-coded tunables</td><td>Deployment-varying values are validated config fields on a plugin row, not constants.</td></tr><tr><td>Fail loud</td><td>Misconfiguration, missing services, malformed packets and connection failures are errors, never silent defaults.</td></tr><tr><td>Bounded resources</td><td>No unbounded queues, buffers or file sinks. Overflow is reported and never stalls gameplay.</td></tr><tr><td>Packet layouts are data</td><td>Structures live in <code>packets/</code>, written once for the baseline and annotated per build; code supplies values by field name.</td></tr><tr><td>Evidence comes from the client</td><td>Layouts and ordering are established by reading the client&#39;s own code; every claim keeps its build-qualified function address.</td></tr><tr><td>English in the code</td><td>Code, comments, XML docs, commit messages, <code>opcodes.yaml</code> and <code>profiles/opcode-policy.md</code> are English.</td></tr><tr><td>Bilingual user documentation</td><td>Update the English guide and its Chinese translation together. Site pages also need Traditional Chinese and Korean.</td></tr></tbody></table><p>No emoji anywhere. Do not cite or name third-party projects, other servers or reference trees; describe designs in this project&#39;s own terms.</p><h2 id="set-up-the-toolchain" tabindex="-1">Set up the toolchain <a class="header-anchor" href="#set-up-the-toolchain" aria-label="Permalink to &quot;Set up the toolchain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Needed for</th><th>Check</th></tr></thead><tbody><tr><td>.NET 10 SDK</td><td>building and running the server</td><td><code>dotnet --version</code> reports 10.x</td></tr><tr><td>Git</td><td>cloning, branches, the validation gate</td><td><code>git --version</code></td></tr><tr><td>Python 3</td><td>CI gate scripts and their unit tests</td><td><code>python --version</code></td></tr><tr><td>Node.js and npm</td><td>documentation site, TypeScript SDK conformance</td><td><code>node --version</code>, <code>npm --version</code></td></tr><tr><td>Go</td><td>Go SDK conformance and tests</td><td><code>go version</code></td></tr><tr><td>Rust with cargo and rustup, plus <code>wasm32-wasip1</code></td><td>Rust SDK conformance and WebAssembly tests</td><td><code>rustc --version</code>; <code>rustup target add wasm32-wasip1</code></td></tr></tbody></table><p>Only .NET and Git are required to build and run the server. The other toolchains are needed by the validation gates, the documentation site and the SDK suites; the gate reports them as missing rather than skipping silently.</p><p>In PowerShell or a shell, from the directory that should hold the checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p><strong>Check it worked.</strong> The clone directory contains <code>BubbleFighter.Fantasy.sln</code>, and the build ends with <code>0 Warning(s)</code> and <code>0 Error(s)</code>.</p><h2 id="build-and-test-locally" tabindex="-1">Build and test locally <a class="header-anchor" href="#build-and-test-locally" aria-label="Permalink to &quot;Build and test locally&quot;">​</a></h2><h3 id="build-the-solution" tabindex="-1">Build the solution <a class="header-anchor" href="#build-the-solution" aria-label="Permalink to &quot;Build the solution&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p>Warnings are errors (<code>TreatWarningsAsErrors</code> is on), and <code>GenerateDocumentationFile</code> requires a meaningful XML summary on every public type and member. Fix the cause; never suppress a warning to get a green build.</p><h3 id="run-the-test-projects" tabindex="-1">Run the test projects <a class="header-anchor" href="#run-the-test-projects" aria-label="Permalink to &quot;Run the test projects&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BubbleFighter.Fantasy.sln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span></span></code></pre></div><p>This is the fast loop while developing. The release gate does not use it directly: it discovers every tracked test project with <code>git ls-files tests/*/*.csproj</code> — including projects outside the solution — and runs them serially with one TRX per project. Give every attempt its own results directory or file name so a rerun cannot overwrite an earlier failure.</p><h3 id="run-the-gate-self-tests" tabindex="-1">Run the gate self-tests <a class="header-anchor" href="#run-the-gate-self-tests" aria-label="Permalink to &quot;Run the gate self-tests&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;test_*.py&quot;</span></span></code></pre></div><p>These tests guard the gate runner itself against false success from empty, missing or skipped reports.</p><h3 id="run-the-public-gate" tabindex="-1">Run the public gate <a class="header-anchor" href="#run-the-public-gate" aria-label="Permalink to &quot;Run the public gate&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/ci/serial-gates.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --results-directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifacts/validation/public-01</span></span></code></pre></div><p>Use a new, non-existent results directory for every attempt; the runner refuses an existing one. It builds Release, runs SDK conformance, runs each test project serially, checks the packet tables and dumps the isolated <code>kr-1256</code> configuration. It ends with <code>PASS public gates: &lt;n&gt; populated test reports, &lt;n&gt; tests, no skips</code> and records the exclusion in <code>scope.json</code>. Public mode runs every tracked test project but excludes only <code>Category=LocalClientData</code> cases; it is not the complete release gate. If <code>CI=true</code> is set, the runner also refuses a checkout that contains <code>.env</code> or <code>profiles/*/local.patch.yaml</code>.</p><p><strong>Check it worked.</strong> The exit code is 0 and the final line is the <code>PASS</code> line above. A nonzero exit prints <code>FAIL &lt;reason&gt;</code>; the log of the failing step is in the results directory.</p><h3 id="run-a-local-host-check" tabindex="-1">Run a local Host check <a class="header-anchor" href="#run-a-local-host-check" aria-label="Permalink to &quot;Run a local Host check&quot;">​</a></h3><p>Follow <a href="./../getting-started/quickstart">Quickstart</a>: copy <code>.env.example</code> to <code>.env</code>, set <code>BFF_MYSQL_PASSWORD</code> to a nonempty disposable value, and always add the isolated patch — including for <code>--dump-config</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/BubbleFighter.Fantasy.Host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> management</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/local-checks/isolated-memory.patch.yaml</span></span></code></pre></div><p>The patch disables <code>persistence.mysql</code> and enables in-memory persistence so a developer <code>.env</code> or local override cannot contact a live database. Never point tests or local checks at a production database. <strong>Check it worked:</strong> another terminal gets <code>{&quot;status&quot;:&quot;ok&quot;, ...}</code> from <code>http://127.0.0.1:8080/health</code>; stop with Ctrl+C.</p><h2 id="repository-map" tabindex="-1">Repository map <a class="header-anchor" href="#repository-map" aria-label="Permalink to &quot;Repository map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>What belongs there</th></tr></thead><tbody><tr><td><code>src/BubbleFighter.Fantasy.Abstractions</code>, <code>src/BubbleFighter.Fantasy.Contracts</code></td><td>shared plugin contracts; loaded once by the host and shared with every plugin</td></tr><tr><td><code>src/BubbleFighter.Fantasy.Kernel</code></td><td>plugin runtime: discovery, activation, service registry, effects, profile composition</td></tr><tr><td><code>src/BubbleFighter.Fantasy.Host</code></td><td>the <code>bff</code> console host and its bootstrap profiles</td></tr><tr><td><code>src/Plugins/</code></td><td>listeners, dialects, game features, persistence, administration and SDK loaders</td></tr><tr><td><code>profiles/</code></td><td>profile rows, bundles, patches and per-build opcode tables</td></tr><tr><td><code>packets/</code></td><td>packet layout data and per-build inheritance</td></tr><tr><td><code>sdk/</code></td><td>optional Python, TypeScript, Go and Rust plugin SDKs</td></tr><tr><td><code>tests/</code></td><td>.NET test projects and shared fixtures</td></tr><tr><td><code>tools/</code></td><td>validation gates (<code>tools/ci</code>), local-check patches (<code>tools/local-checks</code>) and maintenance scripts</td></tr><tr><td><code>docs/</code></td><td>source of the published guides</td></tr><tr><td><code>docs-site/</code></td><td>VitePress site, page allowlist and content sync</td></tr><tr><td><code>deploy/</code></td><td>Docker files and Compose templates</td></tr></tbody></table><h2 id="making-a-change" tabindex="-1">Making a change <a class="header-anchor" href="#making-a-change" aria-label="Permalink to &quot;Making a change&quot;">​</a></h2><h3 id="branch-and-split-the-work" tabindex="-1">Branch and split the work <a class="header-anchor" href="#branch-and-split-the-work" aria-label="Permalink to &quot;Branch and split the work&quot;">​</a></h3><p>Work on your own branch and keep one logical change per commit; the change lands on <code>main</code> only after review. Write commit messages in English: what changed, why, and what evidence supports it.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fix/short-topic</span></span></code></pre></div><h3 id="provide-evidence" tabindex="-1">Provide evidence <a class="header-anchor" href="#provide-evidence" aria-label="Permalink to &quot;Provide evidence&quot;">​</a></h3><ul><li>Add or update tests with the change. For packet work, add byte-pinning tests that fail before the change and pass after it.</li><li>Run the targeted tests, then the full build and test run. Keep the failing output of any earlier attempt; do not overwrite it with a rerun.</li><li>Cite evidence the way the code does: a build-qualified client function address for a wire claim (<code>kr-812 sub_810C20</code>). An opcode row with the observed-session evidence grade names its session in the row, not in code comments.</li><li>In the change description, state what you ran and what it proves; automated tests do not establish real-client acceptance.</li></ul><h3 id="follow-the-plugin-and-resource-rules" tabindex="-1">Follow the plugin and resource rules <a class="header-anchor" href="#follow-the-plugin-and-resource-rules" aria-label="Permalink to &quot;Follow the plugin and resource rules&quot;">​</a></h3><ul><li>Add capability as a plugin row: declare required and provided interfaces in <code>[Plugin(...)]</code>, consume them through <code>IPluginContext</code>, and register only through it.</li><li>Own every registration and external resource with an effect so unloading unwinds it; never leave a background task or queue unbounded.</li><li>Put deployment-varying values in a validated option class on the row (<code>[Required]</code>, <code>[Range]</code>, <code>IValidatableOptions</code>), not in constants.</li><li>Build against the shared contract assemblies; do not ship private copies of <code>Abstractions</code> and <code>Contracts</code> with a plugin.</li><li>Keep public types and members documented with a real XML summary. Write comments that explain why and point at the evidence.</li></ul><h3 id="change-packet-or-opcode-data" tabindex="-1">Change packet or opcode data <a class="header-anchor" href="#change-packet-or-opcode-data" aria-label="Permalink to &quot;Change packet or opcode data&quot;">​</a></h3><p>Read <code>packets/README.md</code> and <code>profiles/opcode-policy.md</code> before touching a layout. In short:</p><ul><li>Write each structure once as the <code>kr-812</code> baseline has it, one named field per line with its client offset; a build that differs annotates the row (<code>except</code>, <code>only</code>, <code>also</code>, or its own replacement). Never add a per-build field table or <code>if (build ...)</code> to code for something the tables can say.</li><li>A field without a proven purpose is <code>unknown_&lt;offset&gt;</code>; do not invent a meaning. Every <code>sub_</code> address is prefixed with its client build.</li><li>Opcode rows record <code>verified</code>, <code>inferred</code>, <code>unverified</code> or <code>observed-session</code> evidence and a <code>name_source</code>; unknown inbound opcodes are logged and never parsed optimistically. C2S and S2C, and game and relay connections, are separate spaces.</li><li>Every codec needs a byte-length-pinning test, and a wire change is checked against the client&#39;s consuming path before it is committed.</li><li>Confirm the tables with <code>bff packets show &lt;build&gt; &lt;structure&gt;</code>, <code>bff packets diff &lt;build&gt; &lt;build&gt;</code> and <code>bff packets check</code>.</li></ul><h2 id="documentation-changes" tabindex="-1">Documentation changes <a class="header-anchor" href="#documentation-changes" aria-label="Permalink to &quot;Documentation changes&quot;">​</a></h2><p><code>docs/</code> is the source of the published guides; <code>docs-site/</code> builds them through the explicit page list in <code>docs-site/pages.json</code>. A published page exists in four files — <code>X.md</code> (English, canonical), <code>X.zh.md</code>, <code>X.zh-tw.md</code> and <code>X.ko.md</code> — and every file needs front matter with <code>title</code>, <code>description</code> and an <code>updated</code> date.</p><ul><li>Local links must point at a published page source, for example <a href="./../guides/configuration">Configuration</a>. External URLs and anchors are fine.</li><li>Do not edit generated content under <code>docs-site/content/</code> or commit build output; both are ignored.</li><li>Update the English and Chinese guides together, and keep all four translations of a site page current.</li><li>Add a dated entry to both root changelogs (<code>CHANGELOG.md</code> and <code>CHANGELOG.zh.md</code>) in the same commit; dates are <code>YYYY-MM-DD</code> and supplied times use Asia/Shanghai. New entries go above older ones.</li></ul><p>Build the site in its own directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The sync step runs before the build and validates metadata and links. It fails with <code>Missing guide metadata: &lt;path&gt;</code> when front matter is incomplete, <code>Missing public guide: &lt;path&gt;</code> when one of the four files is absent, and <code>Unpublished local link: &lt;target&gt;</code> when a local link does not name a published page. Use the other published guides, such as <a href="./../guides/configuration">Configuration</a> and <a href="./../guides/plugins">Plugins</a>, as examples.</p><h2 id="validation-levels" tabindex="-1">Validation levels <a class="header-anchor" href="#validation-levels" aria-label="Permalink to &quot;Validation levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>What runs</th><th>Needs</th><th>What it proves</th></tr></thead><tbody><tr><td>Quick</td><td><code>dotnet build</code> and <code>dotnet test</code></td><td>.NET</td><td>the change compiles and the .NET suites pass</td></tr><tr><td>Public gate</td><td><code>tools/ci/serial-gates.py --public</code></td><td>.NET, Python, Node.js/npm, Go, Rust with <code>wasm32-wasip1</code></td><td>every tracked test project except local-data cases, SDK conformance, packet tables, isolated configuration</td></tr><tr><td>Complete gate</td><td>the same command without <code>--public</code></td><td>the locally provisioned client workbooks below</td><td>every test, no skips; this is the release gate</td></tr><tr><td>Release review</td><td>isolated startup and affected real-client flows</td><td>a real game client</td><td>client acceptance; no automated check replaces it</td></tr></tbody></table><p>The complete gate needs these locally obtained client files; they are not distributed with the repository:</p><table tabindex="0"><thead><tr><th>Setting or path</th><th>Required file</th></tr></thead><tbody><tr><td><code>client-data/cn-324/</code></td><td><code>Config/ShopItem2.xml</code></td></tr><tr><td><code>artifacts/shop-tables-survey/id400/xml/</code></td><td><code>Config/ShopItem2.xml</code></td></tr><tr><td><code>BF_KR1256_UNPACKED_CONFIG</code></td><td><code>Config/ShopItem2.xml</code> and <code>Config/ShopItemPet.xml</code> below that directory</td></tr><tr><td><code>BF_KR1256_FIGHTER_CONFIG</code></td><td>Full path to <code>FighterConfig.xml</code></td></tr></tbody></table><p>If the files are absent, the complete gate prints the missing prerequisites and stops with <code>Local game data is missing for &lt;tests&gt;; provision it or pass --public to run the publicly reproducible gates only.</code></p><p>Report validation honestly:</p><ul><li>Every attempt uses a new results directory; a populated TRX must match passing counters with no failed, empty or skipped results. A skipped test is not a pass.</li><li>Report the mode you ran. The public gate records its exclusion in <code>scope.json</code> and is not the complete release gate.</li><li>Do not delete or rewrite a failing result. Keep the console log and the TRX of a failed attempt.</li><li>Say whether a result came from an automated check or a real game client.</li></ul><p>The public repository workflow runs the publicly reproducible gate on a GitHub-hosted Windows runner for pushes and pull requests to <code>main</code>; it does not run local-data cases. Run the complete gate locally when you have the private client-data prerequisites, and keep <code>.env</code> and local profile patches out of CI checkouts.</p><h2 id="what-a-reviewable-change-contains" tabindex="-1">What a reviewable change contains <a class="header-anchor" href="#what-a-reviewable-change-contains" aria-label="Permalink to &quot;What a reviewable change contains&quot;">​</a></h2><ul><li>A focused diff that does one thing, with tests for the behaviour it changes.</li><li>Validation evidence: the commands, the results, and the failing output before the fix when there was one.</li><li>Data and documentation updates that the change requires: packet tables for wire layouts, opcode rows with evidence, English and Chinese guide updates, and changelog entries.</li><li>No unrelated reformatting, generated files, build output, logs or local overrides.</li></ul><h2 id="what-is-rejected" tabindex="-1">What is rejected <a class="header-anchor" href="#what-is-rejected" aria-label="Permalink to &quot;What is rejected&quot;">​</a></h2><ul><li>Credentials, tokens, <code>.env</code> files, local profile patches, or any secret in code, docs or logs.</li><li>Private investigation material, packet-recording details, client exports or client assets.</li><li>Third-party code, copied layouts or named references to other projects and servers.</li><li>Guessed packet names or field meanings, or handlers enabled on <code>unverified</code> evidence.</li><li>Unbounded queues, buffers or file sinks, and deployment values hard-coded instead of validated configuration.</li><li>A build with suppressed warnings, or a skipped test reported as a pass.</li><li>Generated documentation content, build output, or a feature from an unmerged branch described as available.</li></ul><h2 id="submitting" tabindex="-1">Submitting <a class="header-anchor" href="#submitting" aria-label="Permalink to &quot;Submitting&quot;">​</a></h2><ol><li>Push your branch and open a pull request against <code>main</code>.</li><li>Describe the behaviour change, the evidence and the validation mode you ran; link the failing output if the change fixes a bug.</li><li>Make sure the diff contains no secrets, private material or generated content.</li><li>Answer review comments with another commit or a clear explanation; keep the history reviewable.</li><li>After review, the change is merged into <code>main</code>. Watch the next serial validation run, because the workflow runs there.</li></ol><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li>The project&#39;s GitHub repository is the entry point the README documents: <a href="https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy" target="_blank" rel="noreferrer">https://github.com/Wasabi-FantasyTaleDev/BubbleFighter.Fantasy</a>. The repository documents no chat server or forum.</li><li><a href="./../guides/configuration">Configuration</a> and <a href="./../guides/plugins">Plugins</a> explain the structures a change usually touches.</li><li><a href="./../guides/sdk-protocol">SDK protocol</a> covers the optional language SDKs, and <a href="./../guides/troubleshooting">Troubleshooting</a> helps when a build or gate fails.</li></ul>`,67)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
